import sys
import json
import subprocess
import hashlib
from xml.etree import ElementTree as ET

def compute_keyed_digest(data, key):
    return hashlib.sha256((data + key).encode()).hexdigest()

def process_job(job_element):
    name = job_element.get('name')
    command = job_element.find('command').text
    key = job_element.find('key').text
    expected_digest = job_element.find('digest').text

    result = subprocess.run(command, shell=True, capture_output=True, text=False)
    stdout = result.stdout
    computed_digest = compute_keyed_digest(stdout, key)

    return {
        'name': name,
        'digest_match': computed_digest == expected_digest
    }

def main():
    if len(sys.argv) != 2:
        print("Usage: python jobdigest.py <jobs.xml>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"Error parsing XML file: {e}", file=sys.stderr)
        sys.exit(1)

    jobs = root.findall('job')
    for job in jobs:
        result = process_job(job)
        print(json.dumps(result))

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import json
import subprocess
import hashlib

def compute_keyed_digest(stdout_bytes, key):
    # Use HMAC-SHA256 for keyed digest
    hmac = hashlib.new('hmac', key.encode('utf-8'), hashlib.sha256)
    hmac.update(stdout_bytes)
    return hmac.hexdigest().lower()

def main():
    if len(sys.argv) != 2:
        print("Usage: python jobdigest.py <jobs.xml>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
    except ET.ParseError as e:
        print(f"Error parsing XML file: {e}", file=sys.stderr)
        sys.exit(1)

    for job in root.findall('job'):
        name = job.get('name')
        command = job.find('command').text
        key = job.find('key').text

        try:
            result = subprocess.run(
                command,
                shell=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=False
            )
            stdout_bytes = result.stdout
            digest = compute_keyed_digest(stdout_bytes, key)
            print(json.dumps({
                'name': name,
                'digest': digest
            }))
        except Exception as e:
            print(json.dumps({
                'name': name,
                'digest': f"error: {str(e)}"
            }), file=sys.stderr)

if __name__ == "__main__":
    main()
